61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
65	     * domain containing at least one dot, with no whitespace in any part.
66	     */
67	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
