218	    @Override
219	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner != null) {
222	            Pet pet = owner.getPet(petId);
223	            if (pet != null) {
224	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
225	            }
226	        }
227	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	    }
229	
230	    /**
231	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
232	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
233	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
234	     *
235	     * @param ownerFieldsDto the submitted owner fields
236	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
237	     *                                     name of every offending field
238	     */
239	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
240	        List<String> missingFields = new ArrayList<>();
241	        if (isBlank(ownerFieldsDto.getFirstName())) {
242	            missingFields.add("firstName");
243	        }
244	        if (isBlank(ownerFieldsDto.getLastName())) {
245	            missingFields.add("lastName");
246	        }
247	        if (isBlank(ownerFieldsDto.getAddress())) {
248	            missingFields.add("address");
249	        }
250	        if (isBlank(ownerFieldsDto.getCity())) {
251	            missingFields.add("city");
252	        }
253	        if (isBlank(ownerFieldsDto.getTelephone())) {
254	            missingFields.add("telephone");
255	        }
256	        if (!missingFields.isEmpty()) {
257	            throw new InvalidOwnerFieldsException(missingFields);
258	        }
259	    }
260	
261	    private boolean isBlank(String value) {
262	        return value == null || value.isBlank();
263	    }
264	
265	    /**
266	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
267	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
268	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
269	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
270	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
271	     *
272	     * @param telephone the raw telephone value submitted by the client
273	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
274	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
275	     *                                     400 response
276	     */
277	    private String normalizeTelephone(String telephone) {
278	        String e164 = toE164(telephone);
279	        if (e164 == null) {
280	            throw new InvalidOwnerFieldsException(List.of("telephone"));
281	        }
282	        return e164;
283	    }
284	
285	    /**
286	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
287	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
288	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
289	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
290	     *
291	     * @param telephone the raw telephone value, possibly {@code null}
292	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
293	     */
294	    private String toE164(String telephone) {
295	        if (telephone == null) {
296	            return null;
297	        }
298	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
299	        boolean hasPlus = cleaned.startsWith("+");
300	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
301	        String nationalSignificant = hasPlus
302	            ? digits
303	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
304	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
305	            return null;
306	        }
307	        return "+" + nationalSignificant;
308	    }
309	
310	    /**
311	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
312	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
313	     * returned value is that address lower-cased.
314	     *
315	     * @param email the raw email value submitted by the client, or {@code null} if omitted
316	     * @return the lower-cased email, or {@code null} if none was supplied
317	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
318	     *                                     yielding a 400 response
319	     */
320	    private String normalizeEmail(String email) {
321	        if (email == null) {
322	            return null;
323	        }
324	        if (!EMAIL_PATTERN.matcher(email).matches()) {
325	            throw new InvalidOwnerFieldsException(List.of("email"));
326	        }
327	        return email.toLowerCase(Locale.ROOT);
328	    }
329	
330	    /**
331	     * Builds the owner's {@code customerCode}, formatted {@code '<LAST3>-<NNNN>'}. {@code LAST3} is
332	     * the upper-cased first three letters of the last name, and {@code NNNN} is a global 4-digit
333	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
334	     *
335	     * @param lastName the owner's last name
336	     * @return the formatted customer code
337	     */
338	    private String generateCustomerCode(String lastName) {
339	        String letters = lastName.replaceAll("[^\\p{L}]", "");
340	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
341	        int sequence = this.clinicService.findAllOwners().size() + 1;
342	        return String.format("%s-%04d", last3, sequence);
343	    }
344	
345	    /**
346	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
347	     * telephones are converted to E.164 here as well so the comparison is independent of the format
348	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
349	     * ignored rather than matched.
350	     *
351	     * @param telephone the E.164 telephone of the owner being created
352	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
353	     *                                          yielding a 409 Conflict response
354	     */
355	    private void rejectDuplicateTelephone(String telephone) {
356	        boolean inUse = this.clinicService.findAllOwners().stream()
357	            .map(Owner::getTelephone)
358	            .map(this::toE164)
359	            .anyMatch(telephone::equals);
360	        if (inUse) {
361	            throw new DuplicateOwnerTelephoneException(telephone);
362	        }
363	    }
364	
365	    /**
366	     * Rejects creation of an owner whose last name and address both match an existing owner's,
367	     * which marks them as belonging to the same household. Both the last name and the address are
368	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
369	     * that differ only in letter case or spacing are still treated as a match.
370	     *
371	     * @param lastName the last name of the owner being created
372	     * @param address  the address of the owner being created
373	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
374	     *                                          address, yielding a 409 Conflict response
375	     */
376	    private void rejectDuplicateHousehold(String lastName, String address) {
377	        String normalizedLastName = normalizeForComparison(lastName);
378	        String normalizedAddress = normalizeForComparison(address);
379	        boolean duplicate = this.clinicService.findAllOwners().stream()
380	            .anyMatch(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
381	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress));
382	        if (duplicate) {
383	            throw new DuplicateOwnerHouseholdException(lastName, address);
384	        }
385	    }
386	
387	    /**
388	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
389	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
390	     * the result is lower-cased.
391	     *
392	     * @param value the value to normalize, possibly {@code null}
393	     * @return the normalized value, or an empty string if {@code value} is {@code null}
394	     */
395	    private String normalizeForComparison(String value) {
396	        if (value == null) {
397	            return "";
398	        }
399	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
400	    }
401	}
